// Host tests of the NEXUS ESP32 library (plain C++11, no framework). Usage:
//     test_host <repository root>              run every test; exit status 0 only when all pass
//     test_host <repository root> --emit DIR   additionally write the messages the library produced, for the Python conformance test
// The golden files are read from the repository: contracts/fixtures/firmware-v1 (frozen, taken from the committed firmware) and
// sdk/esp32/test/golden/commands.tsv (generated by tools/gen_golden.py and cross-checked against the contract validator).
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <map>
#include <string>
#include <vector>

#include "NexusSdk.h"

using namespace nexus;

static int checks = 0, failures = 0;
static std::string currentTest;

#define CHECK(cond)                                                                                  \
    do {                                                                                             \
        ++checks;                                                                                    \
        if (!(cond)) {                                                                               \
            ++failures;                                                                              \
            fprintf(stderr, "FAIL [%s] %s:%d: %s\n", currentTest.c_str(), __FILE__, __LINE__, #cond); \
        }                                                                                            \
    } while (0)

#define CHECK_EQ_STR(expected, actual)                                                                         \
    do {                                                                                                       \
        ++checks;                                                                                              \
        std::string e_ = (expected), a_ = (actual);                                                            \
        if (e_ != a_) {                                                                                        \
            ++failures;                                                                                        \
            fprintf(stderr, "FAIL [%s] %s:%d\n  expected: %s\n  actual:   %s\n", currentTest.c_str(), __FILE__, \
                    __LINE__, e_.c_str(), a_.c_str());                                                         \
        }                                                                                                      \
    } while (0)

static std::string root;
static std::string emitDir;
static std::map<std::string, std::string> emitted;

static const char* kDevice = "3f2c8a54-9d1e-4b7a-8c61-0e5d2a7f9b13";
static const char* kCommand = "a1b2c3d4-e5f6-4789-8abc-def012345678";
static const int64_t kNow = 1767225600;  // 2026-01-01T00:00:00Z, the manifest's referenceEpoch

static std::string readFile(const std::string& path, bool* ok = 0) {
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) { if (ok) *ok = false; return std::string(); }
    std::string data;
    char buffer[4096];
    size_t n;
    while ((n = fread(buffer, 1, sizeof(buffer), f)) > 0) data.append(buffer, n);
    fclose(f);
    if (ok) *ok = true;
    return data;
}

static std::string fixture(const char* name) {
    bool ok = false;
    std::string data = readFile(root + "/contracts/fixtures/firmware-v1/" + name, &ok);
    if (!ok) { fprintf(stderr, "cannot read fixture %s\n", name); exit(2); }
    return data;
}

static std::string num(size_t v) {  // std::to_string is missing from some MinGW runtimes
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%lu", (unsigned long)v);
    return buffer;
}

static std::string fileSafe(std::string id) {  // ':' is not allowed in a Windows file name
    for (size_t i = 0; i < id.size(); ++i) if (id[i] == ':') id[i] = '_';
    return id;
}

static void emit(const std::string& name, const std::string& bytes) { emitted[name] = bytes; }

// ---------------------------------------------------------------- the fake platform

struct Sent { std::string topic, payload; bool retained; };

struct FakeHal : Hal {
    int64_t now;
    std::vector<Sent> sent;
    std::vector<bool> led;
    explicit FakeHal(int64_t n) : now(n) {}
    int64_t nowEpochSeconds() override { return now; }
    bool publish(const char* topic, const char* payload, size_t length, bool retained) override {
        Sent s = {topic, std::string(payload, length), retained};
        sent.push_back(s);
        return true;
    }
    void setLed(bool on) override { led.push_back(on); sent.push_back(Sent{"<led>", on ? "on" : "off", false}); }
};

static std::string build(const Telemetry& t, int64_t now, Status* status = 0) {
    char buffer[400];
    size_t n = 0;
    Status st = buildTelemetry(buffer, sizeof(buffer), &n, now, t);
    if (status) *status = st;
    return st == OK ? std::string(buffer, n) : std::string();
}

static std::string ack(int64_t now, const char* id, const char* status, const char* reason, bool versioned, Status* st = 0) {
    char buffer[300];
    size_t n = 0;
    Status s = buildAck(buffer, sizeof(buffer), &n, now, id, status, reason, versioned);
    if (st) *st = s;
    return s == OK ? std::string(buffer, n) : std::string();
}

static bool fromHex(const std::string& hex, std::string* out) {
    out->clear();
    if (hex == "-") return true;
    for (size_t i = 0; i + 1 < hex.size(); i += 2) out->push_back((char)strtol(hex.substr(i, 2).c_str(), 0, 16));
    return true;
}

// ---------------------------------------------------------------- tests

static void testFreshnessRule() {  // P5-085, P5-097
    for (int64_t offset = -200; offset <= 200; ++offset) {
        bool stale = isStale(kNow + offset, kNow);
        bool expected = offset > 30 || offset < -30;
        CHECK(stale == expected);
    }
    CHECK(kCommandFreshnessWindowSeconds == 30);
    CHECK(!isStale(kNow, kNow + 30) && isStale(kNow, kNow + 31));  // a command 30 s in the future is fresh, 31 s is stale
    CHECK(!isStale(kNow, kNow - 30) && isStale(kNow, kNow - 31));
    CHECK(!isStale(2147483647LL, 2147483647LL));
    CHECK(isStale(2147483647LL + 100, 0));  // no overflow on large operands
}

static void testClockGate() {  // P5-099
    CHECK(!clockIsSynced(0) && !clockIsSynced(kMinPlausibleEpoch - 1) && clockIsSynced(kMinPlausibleEpoch));
    Telemetry t = Telemetry::ofNumber(kDevice, "TEMPERATURE_SENSOR", 24.5, "CELSIUS", 0);
    char buffer[300];
    size_t n = 99;
    strcpy(buffer, "stale");
    CHECK(buildTelemetry(buffer, sizeof(buffer), &n, 0, t) == CLOCK_NOT_SYNCED);
    CHECK(buffer[0] == 0 && n == 0);  // nothing is produced, and the caller's length is reset
    CHECK(buildTelemetry(buffer, sizeof(buffer), &n, kMinPlausibleEpoch - 1, t) == CLOCK_NOT_SYNCED);
    CHECK(buildTelemetry(buffer, sizeof(buffer), &n, kMinPlausibleEpoch, t) == OK);
    CHECK(buildAck(buffer, sizeof(buffer), &n, 5, kCommand, "ACCEPTED", 0) == CLOCK_NOT_SYNCED);
    CHECK_EQ_STR("CLOCK_NOT_SYNCED", statusName(CLOCK_NOT_SYNCED));

    // the node: no sample is published and no message id is consumed while the clock is unsynced
    FakeHal hal(0);
    DeviceNode node(hal, kDevice, 0x1122334455667788ULL);
    CHECK(node.publishNumber("TEMPERATURE_SENSOR", 20.0, "CELSIUS") == CLOCK_NOT_SYNCED);
    CHECK(hal.sent.empty() && node.ids().issued() == 0);
    hal.now = kNow;
    CHECK(node.publishNumber("TEMPERATURE_SENSOR", 20.0, "CELSIUS") == OK);
    CHECK(node.ids().issued() == 1);
    // a command before the sync gets no acknowledgement and is not applied (the firmware's first check)
    hal.now = 0;
    std::string led = fixture("command-led-on.json");
    size_t before = hal.sent.size();
    CHECK(node.onCommand((const uint8_t*)led.data(), led.size()) == NO_ACK_CLOCK_NOT_SYNCED);
    CHECK(hal.sent.size() == before && hal.led.empty());
}

static void testTelemetryGolden() {  // P5-095
    // legacy form: byte for byte what the committed firmware produces for the same inputs
    Telemetry legacy = Telemetry::ofNumber(kDevice, "TEMPERATURE_SENSOR", 24.5, "CELSIUS", 0);
    CHECK_EQ_STR(fixture("telemetry-temperature.json"), build(legacy, kNow));

    // contract 1.0 form: same fields in the SDK's order, plus contractVersion and messageId
    MessageIds ids(0xA1B2C3D4E5F60718ULL);
    char id[37];
    CHECK(ids.next(id, sizeof(id)) == OK);
    Telemetry versioned = Telemetry::ofNumber(kDevice, "TEMPERATURE_SENSOR", 24.5, "CELSIUS", id);
    std::string expected = std::string("{\"contractVersion\":\"1.0\",\"deviceId\":\"") + kDevice +
                           "\",\"timestamp\":\"2026-01-01T00:00:00Z\",\"sensorType\":\"TEMPERATURE_SENSOR\",\"value\":24.5,\"unit\":\"CELSIUS\",\"messageId\":\"" +
                           id + "\"}";
    CHECK_EQ_STR(expected, build(versioned, kNow));
    emit("telemetry-versioned.json", expected);
    emit("telemetry-legacy.json", build(legacy, kNow));

    // value kinds and number formatting (a valid JSON number every time; integral doubles keep ".0" like the Python SDK)
    struct { double v; const char* text; } numbers[] = {{25.0, "25.0"}, {-3.5, "-3.5"}, {0.0, "0.0"}, {0.1, "0.1"}, {1e22, "1e+22"},
                                                         {123456.789, "123456.789"}, {2.5e-7, "2.5e-07"}};
    for (size_t i = 0; i < sizeof(numbers) / sizeof(numbers[0]); ++i) {
        std::string out = build(Telemetry::ofNumber(kDevice, "S", numbers[i].v, "U", 0), kNow);
        if (numbers[i].v >= 1e-4 && numbers[i].v < 1e16) CHECK(out.find(std::string("\"value\":") + numbers[i].text + ",") != std::string::npos);
        else CHECK(out.find("e") != std::string::npos);  // exponent spelling differs between C runtimes (e-07, e-007): only the value is compared
        size_t at = out.find("\"value\":") + 8;
        CHECK(fabs(strtod(out.c_str() + at, 0) - numbers[i].v) <= fabs(numbers[i].v) * 1e-15);  // it parses back to the same number
    }
    CHECK(build(Telemetry::ofInteger(kDevice, "S", -42, "U", 0), kNow).find("\"value\":-42,") != std::string::npos);
    CHECK(build(Telemetry::ofInteger(kDevice, "S", 0, "U", 0), kNow).find("\"value\":0,") != std::string::npos);
    Telemetry motionOn = Telemetry::ofBoolean(kDevice, "MOTION_SENSOR", true, "BOOLEAN", 0);
    Telemetry motionOff = Telemetry::ofBoolean(kDevice, "MOTION_SENSOR", false, "BOOLEAN", 0);
    motionOn.capabilityKey = motionOff.capabilityKey = "motion";
    CHECK(build(motionOn, kNow).find("\"value\":true,") != std::string::npos);
    CHECK(build(motionOff, kNow).find("\"value\":false,") != std::string::npos);
    {
        Status refused;  // a boolean needs the generic shape (a capabilityKey); the legacy shape is numeric only
        build(Telemetry::ofBoolean(kDevice, "MOTION_SENSOR", true, "BOOLEAN", 0), kNow, &refused);
        CHECK(refused == INVALID_FIELD);
    }
    std::string big = build(Telemetry::ofInteger(kDevice, "S", -9223372036854775807LL - 1, "U", 0), kNow);
    CHECK(big.find("\"value\":-9223372036854775808,") != std::string::npos);

    // optional members
    Telemetry readback = Telemetry::ofBoolean(kDevice, "LED", true, "BOOLEAN", id);
    readback.capabilityKey = "led";
    readback.readbackCommandId = kCommand;
    std::string rb = build(readback, kNow);
    CHECK(rb.find(",\"capabilityKey\":\"led\",\"readbackCommandId\":\"a1b2c3d4-e5f6-4789-8abc-def012345678\"}") != std::string::npos);
    emit("telemetry-readback.json", rb);
    Telemetry motion = Telemetry::ofBoolean(kDevice, "MOTION_SENSOR", true, "BOOLEAN", id);
    motion.capabilityKey = "motion";
    emit("telemetry-boolean.json", build(motion, kNow));
    emit("telemetry-integer.json", build(Telemetry::ofInteger(kDevice, "COUNTER", 7, "COUNT", id), kNow));

    // refusals, each with its reason
    Status st;
    build(Telemetry::ofNumber("not-a-uuid", "S", 1, "U", 0), kNow, &st); CHECK(st == INVALID_DEVICE_ID);
    build(Telemetry::ofNumber(0, "S", 1, "U", 0), kNow, &st); CHECK(st == INVALID_DEVICE_ID);
    build(Telemetry::ofNumber(kDevice, "S", 1, "U", "msg-0001"), kNow, &st); CHECK(st == INVALID_MESSAGE_ID);
    build(Telemetry::ofNumber(kDevice, "", 1, "U", 0), kNow, &st); CHECK(st == INVALID_FIELD);
    build(Telemetry::ofNumber(kDevice, "S", 1, "", 0), kNow, &st); CHECK(st == INVALID_FIELD);
    build(Telemetry::ofNumber(kDevice, 0, 1, "U", 0), kNow, &st); CHECK(st == INVALID_FIELD);
    build(Telemetry::ofNumber(kDevice, "\xc2\xb0", 1, "U", 0), kNow, &st); CHECK(st == INVALID_FIELD);  // non-ASCII is refused
    build(Telemetry::ofNumber(kDevice, "S\n", 1, "U", 0), kNow, &st); CHECK(st == INVALID_FIELD);
    build(Telemetry::ofNumber(kDevice, "S", NAN, "U", 0), kNow, &st); CHECK(st == NON_FINITE_VALUE);
    build(Telemetry::ofNumber(kDevice, "S", INFINITY, "U", 0), kNow, &st); CHECK(st == NON_FINITE_VALUE);
    build(Telemetry::ofNumber(kDevice, "S", -INFINITY, "U", 0), kNow, &st); CHECK(st == NON_FINITE_VALUE);
    Telemetry badReadback = readback;
    badReadback.readbackCommandId = "x";
    build(badReadback, kNow, &st); CHECK(st == INVALID_COMMAND_ID);
    build(legacy, 253402300800LL, &st); CHECK(st == INVALID_FIELD);  // beyond year 9999

    // quote and backslash in a text field are escaped, so the document stays valid JSON
    std::string quoted = build(Telemetry::ofNumber(kDevice, "A\"B\\C", 1, "U", 0), kNow);
    CHECK(quoted.find("\"sensorType\":\"A\\\"B\\\\C\"") != std::string::npos);

    // a buffer one byte too small fails cleanly at every capacity and never writes past it
    std::string full = build(versioned, kNow);
    for (size_t capacity = 1; capacity <= full.size(); ++capacity) {
        std::vector<char> guarded(capacity + 8, 'G');
        size_t n = 77;
        Status s = buildTelemetry(&guarded[0], capacity, &n, kNow, versioned);
        CHECK(s == BUFFER_TOO_SMALL);
        CHECK(guarded[0] == 0);
        for (size_t k = capacity; k < guarded.size(); ++k) CHECK(guarded[k] == 'G');
    }
    {
        std::vector<char> guarded(full.size() + 1 + 8, 'G');
        size_t n = 0;
        CHECK(buildTelemetry(&guarded[0], full.size() + 1, &n, kNow, versioned) == OK && n == full.size());
        for (size_t k = full.size() + 1; k < guarded.size(); ++k) CHECK(guarded[k] == 'G');
    }
    CHECK(buildTelemetry(0, 10, 0, kNow, versioned) == BUFFER_TOO_SMALL);
    char one[1];
    CHECK(buildTelemetry(one, 0, 0, kNow, versioned) == BUFFER_TOO_SMALL);
}

static void testIsoTimestamps() {
    struct { int64_t epoch; const char* text; } cases[] = {
        {0, "1970-01-01T00:00:00Z"},           {1704067200, "2024-01-01T00:00:00Z"},   {1709164799, "2024-02-28T23:59:59Z"},
        {1709164800, "2024-02-29T00:00:00Z"},  {1709251200, "2024-03-01T00:00:00Z"},   {1767225600, "2026-01-01T00:00:00Z"},
        {1798761599, "2026-12-31T23:59:59Z"},  {4102444800LL, "2100-01-01T00:00:00Z"}, {4107542400LL, "2100-03-01T00:00:00Z"},
        {253402300799LL, "9999-12-31T23:59:59Z"}};
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        char out[21];
        CHECK(formatIsoTimestamp(cases[i].epoch, out, sizeof(out)) == OK);
        CHECK_EQ_STR(cases[i].text, out);
    }
    char small[20];
    CHECK(formatIsoTimestamp(0, small, sizeof(small)) == BUFFER_TOO_SMALL);
    char out[21];
    CHECK(formatIsoTimestamp(-1, out, sizeof(out)) == INVALID_FIELD);
}

static bool looksLikeUuid(const char* s) { return isUuidText(s, strlen(s)); }

static void testMessageIds() {  // P5-096
    MessageIds a(0x0123456789ABCDEFULL), b(0x0123456789ABCDEFULL), otherBoot(0xFEDCBA9876543210ULL);
    std::map<std::string, int> seen;
    for (int i = 1; i <= 5000; ++i) {
        char x[37], y[37], z[37];
        CHECK(a.next(x, sizeof(x)) == OK && b.next(y, sizeof(y)) == OK && otherBoot.next(z, sizeof(z)) == OK);
        CHECK(looksLikeUuid(x));
        CHECK_EQ_STR(x, y);  // a pure function of (boot id, counter)
        CHECK(std::string(x) != z);
        CHECK(seen.count(x) == 0);
        seen[x] = i;
        CHECK(x[14] == '4');  // version 4
        CHECK(strchr("89ab", x[19]) != 0);  // RFC 4122 variant
        for (size_t k = 0; k < 36; ++k) CHECK(!(x[k] >= 'A' && x[k] <= 'F'));  // lowercase
    }
    CHECK(a.issued() == 5000);

    // a retry of the same sample reuses the id; an earlier sample's id can be asked for again
    char first[37], again[37], future[37];
    CHECK(a.idFor(1, first, sizeof(first)) == OK);
    CHECK(a.idFor(1, again, sizeof(again)) == OK);
    CHECK_EQ_STR(first, again);
    CHECK(a.idFor(0, future, sizeof(future)) == INVALID_FIELD);
    CHECK(a.idFor(5001, future, sizeof(future)) == INVALID_FIELD);
    CHECK(a.issued() == 5000);  // asking again does not advance the counter

    // the boot id separates two boots whose counters both restart at 1
    MessageIds reboot(0x0123456789ABCDEEULL);
    char r[37];
    CHECK(reboot.next(r, sizeof(r)) == OK);
    CHECK(std::string(r) != first);

    // the exhaustion bound
    MessageIds nearEnd(1, 0xFFFFFFFEu);
    char e[37];
    CHECK(nearEnd.next(e, sizeof(e)) == OK);
    CHECK(nearEnd.next(e, sizeof(e)) == COUNTER_EXHAUSTED);
    CHECK(nearEnd.next(e, sizeof(e)) == COUNTER_EXHAUSTED);
    char tiny[10];
    MessageIds fresh(2);
    CHECK(fresh.next(tiny, sizeof(tiny)) == BUFFER_TOO_SMALL && fresh.issued() == 0);

    char fixed[37];
    MessageIds::format(0, 0, fixed);
    CHECK_EQ_STR("00000000-0000-4000-8000-000000000000", fixed);
    MessageIds::format(0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFu, fixed);
    CHECK_EQ_STR("ffffffff-ffff-4fff-bfff-ffff00000000", fixed);
    emit("message-id-sample.txt", std::string(first));
}

static void testAckGolden() {  // P5-098
    // legacy form: the committed firmware's bytes
    CHECK_EQ_STR(fixture("ack-accepted.json"), ack(kNow, kCommand, "ACCEPTED", 0, false));
    CHECK_EQ_STR(fixture("ack-rejected-stale.json"), ack(kNow, kCommand, "REJECTED", "STALE", false));
    CHECK_EQ_STR(fixture("ack-rejected-unsupported.json"), ack(kNow, kCommand, "REJECTED", "UNSUPPORTED", false));
    CHECK_EQ_STR(fixture("ack-rejected-malformed.json"), ack(kNow, kCommand, "REJECTED", "MALFORMED", false));
    // contract 1.0 form
    CHECK_EQ_STR("{\"contractVersion\":\"1.0\",\"commandId\":\"a1b2c3d4-e5f6-4789-8abc-def012345678\",\"status\":\"ACCEPTED\",\"timestamp\":1767225600}",
                 ack(kNow, kCommand, "ACCEPTED", 0, true));
    emit("ack-accepted.json", ack(kNow, kCommand, "ACCEPTED", 0, true));
    emit("ack-stale.json", ack(kNow, kCommand, "REJECTED", "STALE", true));
    emit("ack-unsupported.json", ack(kNow, kCommand, "REJECTED", "UNSUPPORTED", true));
    emit("ack-malformed.json", ack(kNow, kCommand, "REJECTED", "MALFORMED", true));
    emit("ack-device-rejected.json", ack(kNow, kCommand, "REJECTED", "DEVICE_REJECTED", true));
    emit("ack-legacy-accepted.json", ack(kNow, kCommand, "ACCEPTED", 0, false));
    emit("ack-uppercase-uuid.json", ack(kNow, "A1B2C3D4-E5F6-4789-8ABC-DEF012345678", "ACCEPTED", 0, true));

    Status st;
    ack(kNow, "cmd-1", "ACCEPTED", 0, true, &st); CHECK(st == INVALID_COMMAND_ID);
    ack(kNow, 0, "ACCEPTED", 0, true, &st); CHECK(st == INVALID_COMMAND_ID);
    ack(kNow, kCommand, "accepted", 0, true, &st); CHECK(st == INVALID_FIELD);  // case-sensitive
    ack(kNow, kCommand, "OK", 0, true, &st); CHECK(st == INVALID_FIELD);
    ack(kNow, kCommand, 0, 0, true, &st); CHECK(st == INVALID_FIELD);
    ack(kNow, kCommand, "ACCEPTED", "STALE", true, &st); CHECK(st == INVALID_FIELD);  // an accepted command carries no reason
    ack(kNow, kCommand, "REJECTED", 0, true, &st); CHECK(st == INVALID_FIELD);        // a rejection always says why
    ack(kNow, kCommand, "REJECTED", "BECAUSE", true, &st); CHECK(st == INVALID_FIELD);
    ack(0, kCommand, "ACCEPTED", 0, true, &st); CHECK(st == CLOCK_NOT_SYNCED);

    std::string full = ack(kNow, kCommand, "REJECTED", "STALE", true);
    for (size_t capacity = 1; capacity <= full.size(); ++capacity) {
        std::vector<char> guarded(capacity + 8, 'G');
        size_t n = 5;
        CHECK(buildAck(&guarded[0], capacity, &n, kNow, kCommand, "REJECTED", "STALE", true) == BUFFER_TOO_SMALL);
        CHECK(guarded[0] == 0);
        for (size_t k = capacity; k < guarded.size(); ++k) CHECK(guarded[k] == 'G');
    }
}

static void testCommandCorpus() {  // P5-097
    std::string text = readFile(root + "/sdk/esp32/test/golden/commands.tsv");
    CHECK(!text.empty());
    size_t cases = 0, pos = 0;
    std::map<std::string, int> counts;
    while (pos < text.size()) {
        size_t eol = text.find('\n', pos);
        if (eol == std::string::npos) eol = text.size();
        std::string line = text.substr(pos, eol - pos);
        pos = eol + 1;
        if (!line.empty() && line[line.size() - 1] == '\r') line.erase(line.size() - 1);  // tolerate a CRLF checkout
        if (line.empty() || line[0] == '#') continue;
        size_t t1 = line.find('\t'), t2 = line.find('\t', t1 + 1), t3 = line.find('\t', t2 + 1);
        CHECK(t1 != std::string::npos && t2 != std::string::npos && t3 != std::string::npos);
        std::string id = line.substr(0, t1), hex = line.substr(t2 + 1, t3 - t2 - 1), expected = line.substr(t3 + 1);
        int64_t now = atoll(line.substr(t1 + 1, t2 - t1 - 1).c_str());
        std::string payload;
        fromHex(hex, &payload);
        currentTest = "command corpus: " + id;
        CommandResult r = evaluateCommand((const uint8_t*)payload.data(), payload.size(), now);
        CHECK_EQ_STR(expected, dispositionName(r.disposition));
        counts[expected]++;
        ++cases;

        // the same case through the reference device: exactly one acknowledgement iff the disposition acknowledges, the LED only when accepted
        FakeHal hal(now);
        DeviceNode node(hal, kDevice, 0x42ULL);
        Disposition d = node.onCommand((const uint8_t*)payload.data(), payload.size());
        CHECK(d == r.disposition);
        size_t acks = 0, leds = 0;
        for (size_t i = 0; i < hal.sent.size(); ++i) {
            if (hal.sent[i].topic == std::string("nexus/devices/") + kDevice + "/commands/ack") {
                ++acks;
                emit("conformance/" + fileSafe(id) + ".ack", hal.sent[i].payload);
            }
            if (hal.sent[i].topic == "<led>") ++leds;
        }
        CHECK(acks == (dispositionAcknowledges(d) ? 1u : 0u));
        CHECK(leds == (d == ACCEPTED ? 1u : 0u));
        if (d == ACCEPTED) CHECK(hal.led[0] == r.value);
        CHECK(node.lastStatus() == OK);
    }
    currentTest = "command corpus";
    CHECK(cases >= 100);
    CHECK(counts["ACCEPTED"] > 0 && counts["REJECTED:STALE"] > 0 && counts["REJECTED:UNSUPPORTED"] > 0 && counts["REJECTED:MALFORMED"] > 0);
    CHECK(counts["NO_ACK:NOT_JSON"] > 0 && counts["NO_ACK:NO_COMMAND_ID"] > 0 && counts["NO_ACK:CLOCK_NOT_SYNCED"] > 0);
    emit("conformance/cases.txt", num(cases));
}

static void testCommandEdges() {
    // a payload that is not NUL terminated is never read past its length
    std::string led = fixture("command-led-on.json");
    std::vector<uint8_t> exact(led.begin(), led.end());
    exact.push_back('x');  // a byte after the document that the length excludes
    CommandResult r = evaluateCommand(&exact[0], led.size(), kNow);
    CHECK(r.disposition == ACCEPTED && r.value && r.timestamp == kNow);
    CHECK_EQ_STR(kCommand, r.commandId);
    CHECK(evaluateCommand(0, 0, kNow).disposition == NO_ACK_NOT_JSON);
    CHECK(evaluateCommand(0, 5, kNow).disposition == NO_ACK_NOT_JSON);
    // every prefix of a valid command is refused without a crash or a read past the end
    for (size_t len = 0; len < led.size(); ++len) {
        std::vector<uint8_t> prefix(led.begin(), led.begin() + len);
        prefix.push_back(0);
        Disposition d = evaluateCommand(&prefix[0], len, kNow).disposition;
        CHECK(d == NO_ACK_NOT_JSON);
    }
    // nesting beyond the library bound is refused (documented bound)
    std::string deep = "{\"a\":" + std::string(40, '[') + std::string(40, ']') + "}";
    CHECK(evaluateCommand((const uint8_t*)deep.data(), deep.size(), kNow).disposition == NO_ACK_NOT_JSON);
    // too many members is refused (documented bound)
    std::string many = "{";
    for (int i = 0; i < 120; ++i) many += (i ? "," : "") + std::string("\"k") + num(i) + "\":1";
    many += "}";
    CHECK(many.size() < kMaxCommandPayload + 1000);
    CHECK(evaluateCommand((const uint8_t*)many.data(), many.size(), kNow).disposition == NO_ACK_NOT_JSON);
    // the result never exposes a command id unless it acknowledges
    CommandResult none = evaluateCommand((const uint8_t*)"{}", 2, kNow);
    CHECK(none.commandId[0] == 0 && !dispositionAcknowledges(none.disposition));
    CHECK(dispositionAckStatus(ACCEPTED) != 0 && dispositionAckReason(ACCEPTED) == 0);
    CHECK_EQ_STR("STALE", dispositionAckReason(REJECTED_STALE));
    CHECK(dispositionAckStatus(NO_ACK_NOT_JSON) == 0);
}

static void testTopics() {
    char t[100];
    CHECK(topicTelemetry(t, sizeof(t), kDevice) == OK);
    CHECK_EQ_STR(std::string("nexus/devices/") + kDevice + "/telemetry", t);
    CHECK(topicStatus(t, sizeof(t), kDevice) == OK);
    CHECK_EQ_STR(std::string("nexus/devices/") + kDevice + "/status", t);
    CHECK(topicCommand(t, sizeof(t), kDevice) == OK);
    CHECK_EQ_STR(std::string("nexus/devices/") + kDevice + "/commands", t);
    CHECK(topicAck(t, sizeof(t), kDevice) == OK);
    CHECK_EQ_STR(std::string("nexus/devices/") + kDevice + "/commands/ack", t);
    CHECK(topicAck(t, 20, kDevice) == BUFFER_TOO_SMALL);
    CHECK(topicAck(t, sizeof(t), "nope") == INVALID_DEVICE_ID && t[0] == 0);
    CHECK_EQ_STR("online", statusPayload(true));
    CHECK_EQ_STR("offline", statusPayload(false));
}

static void testReferenceDevice() {  // P5-101, P5-096
    FakeHal hal(kNow);
    DeviceNode node(hal, kDevice, 0xDEADBEEFCAFEF00DULL);
    CHECK(node.begin() == OK);
    CHECK(node.publishStatus(true) == OK);
    CHECK(hal.sent.size() == 1 && hal.sent[0].payload == "online" && hal.sent[0].retained);
    CHECK_EQ_STR(std::string("nexus/devices/") + kDevice + "/status", hal.sent[0].topic);

    CHECK(node.publishNumber("TEMPERATURE_SENSOR", 24.5, "CELSIUS") == OK);
    CHECK(node.publishNumber("TEMPERATURE_SENSOR", 24.5, "CELSIUS") == OK);
    CHECK(hal.sent.size() == 3);
    CHECK(hal.sent[1].payload != hal.sent[2].payload);  // two samples, two ids
    // QoS 1 style redelivery: the identical bytes, hence the identical message id
    CHECK(node.retryLast() == OK);
    CHECK(hal.sent.size() == 4 && hal.sent[3].payload == hal.sent[2].payload && hal.sent[3].topic == hal.sent[2].topic);
    // a later new sample moves on
    CHECK(node.publishBoolean("MOTION_SENSOR", true, "BOOLEAN", "motion") == OK);
    CHECK(hal.sent[4].payload != hal.sent[2].payload);
    CHECK(node.ids().issued() == 3);
    emit("reference/sample-1.json", hal.sent[1].payload);
    emit("reference/sample-2.json", hal.sent[2].payload);
    emit("reference/sample-3.json", hal.sent[4].payload);

    // a provisioned device id that is not a UUID is refused up front and the node publishes nothing
    FakeHal other(kNow);
    DeviceNode broken(other, "device-7", 1);
    CHECK(broken.begin() == INVALID_DEVICE_ID);
    CHECK(broken.publishStatus(true) == INVALID_DEVICE_ID && broken.publishNumber("S", 1, "U") == INVALID_DEVICE_ID);
    CHECK(other.sent.empty());
    CHECK(broken.retryLast() == INVALID_DEVICE_ID);

    // retry with nothing sent
    FakeHal fresh(kNow);
    DeviceNode empty(fresh, kDevice, 3);
    CHECK(empty.retryLast() == INVALID_FIELD && fresh.sent.empty());

    // a refused sample (bad arguments) does not consume an id
    CHECK(empty.publishNumber("", 1.0, "U") == INVALID_FIELD);
    CHECK(empty.ids().issued() == 0);
    CHECK(empty.publishNumber("S", NAN, "U") == NON_FINITE_VALUE && empty.ids().issued() == 0);

    // legacy acknowledgements for a node that must match the committed firmware byte for byte
    FakeHal legacyHal(kNow);
    DeviceNode legacy(legacyHal, kDevice, 5, false);
    std::string led = fixture("command-led-on.json");
    CHECK(legacy.onCommand((const uint8_t*)led.data(), led.size()) == ACCEPTED);
    CHECK(legacyHal.sent.size() == 2 && legacyHal.sent[0].topic == "<led>");  // the LED is applied before the acknowledgement
    CHECK_EQ_STR(fixture("ack-accepted.json"), legacyHal.sent[1].payload);
}

int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr, "usage: test_host <repository root> [--emit DIR]\n"); return 2; }
    root = argv[1];
    if (argc >= 4 && std::string(argv[2]) == "--emit") emitDir = argv[3];

    struct { const char* name; void (*run)(); } tests[] = {
        {"freshness rule", testFreshnessRule},   {"clock gate", testClockGate},       {"telemetry golden", testTelemetryGolden},
        {"iso timestamps", testIsoTimestamps},   {"message ids", testMessageIds},     {"ack golden", testAckGolden},
        {"command corpus", testCommandCorpus},   {"command edges", testCommandEdges}, {"topics", testTopics},
        {"reference device", testReferenceDevice}};
    for (size_t i = 0; i < sizeof(tests) / sizeof(tests[0]); ++i) {
        currentTest = tests[i].name;
        int before = failures;
        tests[i].run();
        printf("%-18s %s\n", tests[i].name, failures == before ? "ok" : "FAILED");
    }
    printf("%d checks, %d failures\n", checks, failures);

    if (!emitDir.empty()) {
        for (std::map<std::string, std::string>::const_iterator it = emitted.begin(); it != emitted.end(); ++it) {
            std::string path = emitDir + "/" + it->first;
            for (size_t k = 0; k < path.size(); ++k) if (path[k] == '\\') path[k] = '/';
            FILE* f = fopen(path.c_str(), "wb");
            if (!f) { fprintf(stderr, "cannot write %s\n", path.c_str()); return 2; }
            fwrite(it->second.data(), 1, it->second.size(), f);
            fclose(f);
        }
        printf("emitted %d files\n", (int)emitted.size());
    }
    return failures == 0 ? 0 : 1;
}
